const input = $input.first()?.json ?? {};
const documentId = String(input.document_id ?? '').trim();
if (!documentId) throw new Error('document_id is required');
const stringList = (value) => {
  if (!Array.isArray(value)) return [];
  return [...new Set(value.map((item) => String(item ?? '').trim()).filter(Boolean))];
};
const visibility = input.visibility === 'public' ? 'public' : 'restricted';
const accessGroups = stringList(input.access_groups);
if (visibility === 'restricted' && accessGroups.length === 0) {
  throw new Error('restricted documents require at least one access_group');
}
return [{ json: {
  document_id: documentId,
  options: {
    tenant_id: String(input.tenant_id ?? 'default').trim() || 'default',
    visibility,
    access_groups: accessGroups,
    source_type: String(input.source_type ?? 'project_document').trim() || 'project_document',
    source_url: String(input.source_url ?? '').trim(),
    decision_steps: stringList(input.decision_steps),
    project_types: stringList(input.project_types),
    geography: stringList(input.geography),
    metadata: input.metadata && typeof input.metadata === 'object' && !Array.isArray(input.metadata) ? input.metadata : {},
  },
} }];
